properties.unscaledStyleSheet:
QMenuBar {
    background-color: transparent;
    color: @text-secondary;
    font-size: 12px;
    border: none;
    spacing: 0px;
}
QMenuBar::item {
    background-color: transparent;
    padding: 4px 10px;
}
QMenuBar::item:selected {
    background-color: @surface-hover;
    color: @text-heading;
}
QMenuBar::item:pressed {
    background-color: @surface-active;
}
QMenu::separator {
    height: 1px;
    background-color: @surface-hover;
    margin: 4px 8px;
}

